function usuarioCtrl($scope,_mS,_commonSvc,_modalSvc,_nombreModalConst,toast,decodeToken){let accion=JSON.parse(localStorage.getItem("accion"));null===accion?location.href="/Home/Index":$scope.accion=accion[0];let idUsuarioRol=parseInt(decodeToken.idUsuarioRol);$scope.dataSearch={idRol:idUsuarioRol,pageIndex:1,pageSize:100},$scope.maxSize=5,$scope.totalRecords=0,$scope.recordsQuantity=[5,10,25,50],$scope.getUsuarios=function(){try{_commonSvc.getDataApi({method:"get",url:`apiCliente/Usuario/Get/${JSON.stringify($scope.dataSearch)}`,typeUrl:1}).then(response=>{0==response.id&&console.warn(response),$scope.usuarios=JSON.parse(response.data),$scope.$apply()}).catch(error=>{let msg=error.config?error.config.url:error;console.error(msg)})}catch(error){console.log(error)}},$scope.getUsuarios(),$scope.pagechanged=function(){$scope.getUsuarios()},$scope.changePageSize=function(){$scope.dataSearch.pageIndex=1,$scope.getUsuarios()},$scope.openModalUserNew=async()=>{let{MODAL_CTRL:MODAL_CTRL,MODAL_NUEVO:MODAL_NUEVO}=_nombreModalConst.user,controller=(await import("./../../"+MODAL_CTRL))[MODAL_NUEVO.controller],template=MODAL_NUEVO.template,params={tipoRegistro:"N"};$scope.openModalParam({controller:controller,template:template,params:params})},$scope.openModalUserEdit=async item=>{let{MODAL_CTRL:MODAL_CTRL,MODAL_EDIT:MODAL_EDIT}=_nombreModalConst.user,controller=(await import("./../../"+MODAL_CTRL))[MODAL_EDIT.controller],template=MODAL_EDIT.template,params={data:item,tipoRegistro:"E"};$scope.openModalParam({controller:controller,template:template,params:params,size:"md"})},$scope.openModalParam=async({controller:controller,template:template,size:size="lg",params:params})=>{_modalSvc.openModalCustom({controller:controller,template:template,size:size,params:params}).result.then(result=>{"object"==typeof result&&$scope.getUsuarios()})},$scope.openModalUserCompany=async item=>{let{MODAL_CTRL:MODAL_CTRL,MODAL_USER_COMPANY:MODAL_USER_COMPANY}=_nombreModalConst.user,controller=(await import("./../../"+MODAL_CTRL))[MODAL_USER_COMPANY.controller],template=MODAL_USER_COMPANY.template;_modalSvc.openModalCustom({controller:controller,template:template,size:"xl",params:item})},$scope.askToDelete=async item=>{const swalWithBootstrapButtons=Swal.mixin({customClass:{confirmButton:"btn btn-success",cancelButton:"btn btn-danger ml-2"},buttonsStyling:!1});let{isConfirmed:isConfirmed}=await swalWithBootstrapButtons.fire({title:"<small>Eliminar Usuario</small>",html:"<small>Este proceso no puedes revertir!</small>",icon:"warning",showCancelButton:!0,confirmButtonText:"Si, eliminar!",cancelButtonText:"No, cancelar!",reverseButtons:!1,allowOutsideClick:!1});isConfirmed&&_mS.getData("post","/Usuario/Delete?idUsuario="+item.idUsuario).then(response=>{"0"==response.id&&toast.toastr("warning",response.message,response.titleSms),"1"==response.id&&(toast.toastr("success",response.message,response.titleSms),$scope.getUsuarios())})}}app.controller("usuarioCtrl",usuarioCtrl),usuarioCtrl.$inject=["$scope","mainService","commonService","modalService","nombreModal","toastService","decodeToken"];